/// Material themes built from the guide, for your MaterialApp:
/// theme: MotifTheme.light(), darkTheme: MotifTheme.dark().
abstract final class MotifTheme {
  /// Set by Motif's screenshots. Leave it null in your app.
  static MotifVariant? debugVariantOverride;

  /// The light theme for a variant (the default one unless you pass another).
  static ThemeData light({MotifVariant variant = MotifVariant.defaultVariant}) {
    final colors = switch (debugVariantOverride ?? variant) {
      MotifVariant.defaultVariant => MotifColors.light,
      MotifVariant.kids => MotifColors.kidsLight,
    };
    return _theme(Brightness.light, colors);
  }

  /// The dark theme for a variant (the default one unless you pass another).
  static ThemeData dark({MotifVariant variant = MotifVariant.defaultVariant}) {
    final colors = switch (debugVariantOverride ?? variant) {
      MotifVariant.defaultVariant => MotifColors.dark,
      MotifVariant.kids => MotifColors.kidsDark,
    };
    return _theme(Brightness.dark, colors);
  }

  static ThemeData _theme(Brightness brightness, MotifColors colors) {
    return ThemeData(
      useMaterial3: true,
      colorScheme: ColorScheme(
        brightness: brightness,
        primary: colors.actionPrimary,
        onPrimary: colors.onActionPrimary,
        secondary: colors.actionSecondary,
        onSecondary: colors.onActionSecondary,
        error: colors.danger,
        onError: colors.onDanger,
        surface: colors.surface,
        onSurface: colors.textPrimary,
        onSurfaceVariant: colors.textSecondary,
        surfaceContainerLow: colors.background,
        surfaceContainer: colors.surface,
        surfaceContainerHigh: colors.surfaceRaised,
        surfaceContainerHighest: colors.surfaceRaised,
        outline: colors.border,
        outlineVariant: colors.border,
        inverseSurface: colors.textPrimary,
        onInverseSurface: colors.textInverse,
        surfaceTint: colors.surface,
      ),
      scaffoldBackgroundColor: colors.background,
      dividerColor: colors.border,
      textTheme: TextTheme(
        displayLarge: MotifText.display,
        displayMedium: MotifText.display,
        displaySmall: MotifText.display,
        headlineLarge: MotifText.title,
        headlineMedium: MotifText.title,
        headlineSmall: MotifText.title.copyWith(fontSize: 20),
        titleLarge: MotifText.heading,
        titleMedium: MotifText.heading.copyWith(fontSize: 16),
        titleSmall: MotifText.heading.copyWith(fontSize: 14),
        bodyLarge: MotifText.body,
        bodyMedium: MotifText.body.copyWith(fontSize: 14),
        bodySmall: MotifText.caption,
        labelLarge: MotifText.label,
        labelMedium: MotifText.label.copyWith(fontSize: 12),
        labelSmall: MotifText.label.copyWith(fontSize: 12),
      ),
      extensions: [colors],
    );
